/**
 * `authorize`: a reading of a grant table, nothing more. A principal may run a command about a resource when a row
 * names the command and one of its subject sets holds for the principal under the row's scope. There is no
 * precedence, no deny and no admin shortcut in this function: `Admin` is a subject set like any other, and its
 * rows are data (ADR 0001).
 *
 * The table is the data of this function, its test oracle and the table a board member reads
 * (`docs/system/teams.md`, generated by `tools/docgen`).
 */
import { Array as Arr, Effect, Predicate } from "effect";
import type { NonEmptyReadonlyArray } from "effect/Array";

import { Forbidden } from "../shared/errors.ts";
import type * as Grant from "./grant.ts";
import { CurrentPrincipal } from "./principal.ts";
import type { Principal } from "./principal.ts";
import * as Subject from "./subject.ts";

export type { Resource } from "./subject.ts";

/** Whether `principal` may run `command` about `resource`. */
export type Authorize<Command extends string> = (
  principal: Principal,
  command: Command,
  resource?: Subject.Resource
) => boolean;

/** Whether `principal` may run `command` for at least one department, or for everything. */
export type CanAnywhere<Command extends string> = (
  principal: Principal,
  command: Command
) => boolean;

/** The current principal when it may run `command` about every one of `resources`; `Forbidden` otherwise. */
export type RequireGrant<Command extends string> = (
  command: Command,
  resources: Subject.Resource | NonEmptyReadonlyArray<Subject.Resource>
) => Effect.Effect<Principal, Forbidden, CurrentPrincipal>;

/**
 * `authorize` over `table`. The command is any name a row can carry: a command of a domain's `RpcGroup`, or a
 * read the domain declares.
 */
export const authorizeWith =
  <Command extends string>(
    table: readonly Grant.Row<Command>[]
  ): Authorize<Command> =>
  (principal, command, resource = {}) =>
    Arr.some(
      table,
      (row) =>
        Arr.contains(row.commands, command) &&
        Arr.some(row.subjects, (subject) =>
          Subject.holds(subject, row.scope, principal, resource)
        )
    );

/**
 * Whether the principal may run `command` for at least one department it belongs to, or for everything. A command
 * that only a person's own records allow (scope `own`) is not counted: it needs a record, and a page without one
 * has nothing to show. The control panel's sidebar asks this to decide which sections to offer.
 */
export const canAnywhereWith = <Command extends string>(
  table: readonly Grant.Row<Command>[]
): CanAnywhere<Command> => {
  const authorize = authorizeWith(table);

  return (principal, command) =>
    authorize(principal, command) ||
    (Predicate.isTagged(principal, "Person") &&
      Arr.some(principal.memberships, (membership) =>
        authorize(principal, command, { departmentId: membership.departmentId })
      ));
};

/**
 * Fails with `Forbidden` unless the current principal may run `command` about every one of `resources` (a move
 * between departments names two). Answers the principal, so the command can audit it.
 */
export const requireGrantWith = <Command extends string>(
  table: readonly Grant.Row<Command>[]
): RequireGrant<Command> => {
  const authorize = authorizeWith(table);

  return Effect.fnUntraced(function* requireGrant(command, resources) {
    const principal = yield* CurrentPrincipal;
    const named = Arr.ensure(resources);

    if (
      Arr.every(named, (resource) => authorize(principal, command, resource))
    ) {
      return principal;
    }

    return yield* new Forbidden({ command });
  });
};
